class BytesIOCopy:
    """A binary stream, backed by a real temporary file so it has a usable
    file descriptor, that copies everything written to it to another stream.

    Having a real file descriptor allows the redirected `<stdout>`/`<stderr>`
    streams to be used as the ``stdout``/``stderr`` argument of
    :func:`subprocess.run` and similar APIs.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self.copy_to = copy_to
        self._file: t.BinaryIO = tempfile.TemporaryFile()

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

